// Creates .env.fork with two fresh fork-only keys (hub and bot). Prints addresses only, never key values.
import { existsSync, writeFileSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { parseEnv } from 'node:util';
import { generateForkKey, keyFromEnvFile } from '../packages/core/src/fork.ts';
const file = resolve(import.meta.dirname, '..', '.env.fork');
if (!existsSync(file)) {
  const hub = generateForkKey(), bot = generateForkKey();
  writeFileSync(file, [
    '# Fork-only keys generated by scripts/fork-keys.ts. Gitignored. Never fund these on mainnet.',
    `SUI_HUB_KEY=${hub.secret}`,
    `YOJIMBO_BOT_KEY=${bot.secret}`,
    'YOJIMBO_SUI_FORK_RPC=http://127.0.0.1:9796',
    'YOJIMBO_ALLOW_FORK_WRITES=LOCAL_FORK_ONLY',
    'YOJIMBO_FORK_RULES=docs/fork-rules.json',
    'YOJIMBO_MAX_DEFENCE_USDC=10',
    'YOJIMBO_DAILY_USDC=30',
    'PORT=8796',
    'VITE_PORT=5186',
    '',
  ].join('\n'), { mode: 0o600 });
}
const names = Object.keys(parseEnv(readFileSync(file, 'utf8')));
for (const name of ['SUI_HUB_KEY', 'YOJIMBO_BOT_KEY']) if (!names.includes(name)) throw new Error(`${file} lacks ${name}`);
console.log(JSON.stringify({ envFile: file, hub: keyFromEnvFile(file, 'SUI_HUB_KEY').toSuiAddress(), bot: keyFromEnvFile(file, 'YOJIMBO_BOT_KEY').toSuiAddress() }));
